'use strict';
const KEY='beready.v1';
const defaultData={
 subjects:[
  {id:'math',name:'Combined Mathematics',icon:'∑',color:'#e6e9ff'},
  {id:'physics',name:'Physics',icon:'⚛',color:'#e0f5e0'},
  {id:'chem',name:'Chemistry',icon:'⚗',color:'#fff0e6'}
 ],
 tasks:[],sessions:[],events:[],notes:[],documents:[],flashcards:[],syllabus:[],
 settings:{dailyTarget:4,weeklyTarget:28,study:25,shortBreak:5,longBreak:15,longAfter:4,sound:true,vibrate:true},
 timer:{status:'idle',mode:'study',remainingMs:1500000,subjectId:'',endAt:0,startedAt:0,sessionId:'',completedToday:0},
 dashboard:{subjects:true,tasks:true,timetable:true,weekly:true}
};
let data=loadData(),tab='home',taskFilter='today',taskQuery='',analyticsRange=7,calendarDate=new Date(),selectedCalendar='',timerTick=null,flashIndex=0,flashReveal=false;
function loadData(){try{const x=JSON.parse(localStorage.getItem(KEY));return x?Object.assign(defaultData,x,{settings:Object.assign({},defaultData.settings,x.settings||{}),dashboard:Object.assign({},defaultData.dashboard,x.dashboard||{}),timer:Object.assign({},defaultData.timer,x.timer||{})}):JSON.parse(JSON.stringify(defaultData))}catch(e){return JSON.parse(JSON.stringify(defaultData))}}
function save(){localStorage.setItem(KEY,JSON.stringify(data))}
function id(){return Date.now().toString(36)+Math.random().toString(36).slice(2,7)}
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function dayKey(d=new Date()){const x=new Date(d);return x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0')}
function dateFrom(k){const a=k.split('-').map(Number);return new Date(a[0],a[1]-1,a[2])}
function fmtDate(k){return dateFrom(k).toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}
function timeFmt(ms){let s=Math.max(0,Math.floor(ms/1000));return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
function mins(ms){return Math.round(ms/60000)}
function duration(ms){let m=Math.max(0,Math.round(ms/60000));return Math.floor(m/60)+'h '+(m%60)+'m'}
function subjectName(sid){let s=data.subjects.find(x=>x.id===sid);return s?s.name:'General study'}
function subjectColor(sid){let s=data.subjects.find(x=>x.id===sid);return s?s.color:'#e6e9ff'}
function sumSessions(list){return list.reduce((a,s)=>a+(Number(s.durationMs)||0),0)}
function sessionsOn(k){return data.sessions.filter(s=>s.date===k)}
function sessionsFor(sid){return data.sessions.filter(s=>s.subjectId===sid)}
function allStudyDays(){return [...new Set(data.sessions.filter(s=>s.durationMs>0).map(s=>s.date))].sort()}
function streak(){let days=allStudyDays(),set=new Set(days),cur=0,check=new Date();if(!set.has(dayKey(check))){check.setDate(check.getDate()-1)}while(set.has(dayKey(check))){cur++;check.setDate(check.getDate()-1)}let best=0,n=0,prev=null;days.forEach(k=>{let d=dateFrom(k);if(prev){let diff=(d-prev)/86400000;n=diff===1?n+1:1}else n=1;best=Math.max(best,n);prev=d});return {cur,best}}
function greeting(){let h=new Date().getHours();return h<12?'GOOD MORNING':h<17?'GOOD AFTERNOON':'GOOD EVENING'}
function toast(msg){let el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2300)}
function empty(msg,ico='✦'){return '<div class="empty"><span>'+ico+'</span>'+esc(msg)+'</div>'}
function section(title,action='',label='View all'){return '<div class="section-head"><h2>'+title+'</h2>'+(action?'<button data-action="'+action+'">'+label+' →</button>':'')+'</div>'}
function subjectOptions(selected=''){return '<option value="">Choose subject</option>'+data.subjects.map(s=>'<option value="'+esc(s.id)+'" '+(s.id===selected?'selected':'')+'>'+esc(s.name)+'</option>').join('')}
function pageTitle(title,sub,btn=''){return '<div class="page-title"><div><h1>'+title+'</h1><p>'+sub+'</p></div>'+btn+'</div>'}
function render(){
 document.getElementById('greeting').textContent=greeting();
 document.getElementById('todayLabel').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'short',day:'numeric'});
 document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));
 const root=document.getElementById('screen');
 root.innerHTML=tab==='home'?homeView():tab==='tasks'?tasksView():tab==='timer'?timerView():tab==='library'?libraryView():moreView();
 if(tab==='timer')startTicker();else stopTicker();
}
function homeView(){
 const today=dayKey(),todayMs=sumSessions(sessionsOn(today)),target=data.settings.dailyTarget*3600000,done=data.tasks.filter(t=>t.date===today&&t.done).length,pending=data.tasks.filter(t=>t.date===today&&!t.done).length,poms=sessionsOn(today).filter(s=>s.type==='pomodoro').length,pct=target?Math.min(100,Math.round(todayMs/target*100)):0;
 const upcoming=data.events.map(e=>({e,at:nextEventDate(e)})).filter(x=>x.at>Date.now()).sort((a,b)=>a.at-b.at)[0];
 let html='<div class="hero"><div class="hero-row"><div><div class="eyebrow">YOUR DAILY MOMENTUM</div><h2>'+duration(todayMs)+'</h2><p>of '+data.settings.dailyTarget+'h daily study goal</p><div style="margin-top:16px"><button class="primary-btn" data-tab="timer">Start studying ↗</button></div></div><div class="progress-ring" style="--pct:'+pct+'%"><span>'+pct+'%</span></div></div></div>';
 html+='<div class="stats-grid"><div class="stat-card"><div class="stat-icon">✓</div><strong>'+done+' / '+(done+pending)+'</strong><small>Tasks completed today</small></div><div class="stat-card"><div class="stat-icon">◷</div><strong>'+poms+'</strong><small>Focus sessions today</small></div></div>';
 if(data.dashboard.subjects){html+=section('Your subjects','subjects','Manage');html+='<div class="subject-grid">'+data.subjects.map(s=>{let sm=sumSessions(sessionsOn(today).filter(x=>x.subjectId===s.id)),all=sumSessions(sessionsFor(s.id));let sp=data.settings.dailyTarget?Math.min(100,sm/target*100):0;return '<button class="subject-card" data-action="subject-detail" data-id="'+s.id+'"><div class="subject-top"><span class="subject-icon" style="background:'+s.color+'">'+esc(s.icon)+'</span><span class="pill">'+duration(all)+'</span></div><b>'+esc(s.name)+'</b><small>'+duration(sm)+' today</small><div class="mini-track"><i style="width:'+sp+'%;background:'+s.color+'"></i></div></button>'}).join('')+'</div>'}
 if(data.dashboard.tasks){let ts=data.tasks.filter(t=>t.date===today&&!t.done).sort((a,b)=>priorityRank(a)-priorityRank(b)).slice(0,3);html+=section("Today's tasks",'tasks');html+='<div class="card list-card">'+(ts.length?ts.map(taskRow).join(''):empty('Nothing pending. Add a task when you are ready.','✓'))+'</div>'}
 if(data.dashboard.timetable){html+=section('Next on your timetable','timetable');html+='<div class="card">'+(upcoming?'<div class="rowline"><span class="subject-icon" style="background:'+subjectColor(upcoming.e.subjectId)+'">◷</span><div style="flex:1"><b>'+esc(upcoming.e.title||subjectName(upcoming.e.subjectId))+'</b><div class="sub">'+subjectName(upcoming.e.subjectId)+' · '+new Date(upcoming.at).toLocaleString(undefined,{weekday:'short',hour:'2-digit',minute:'2-digit'})+'</div></div><span class="pill orange">Upcoming</span></div>':empty('No upcoming sessions scheduled','◷'))+'</div>'}
 if(data.dashboard.weekly){let arr=lastDays(7),weekMs=sumSessions(data.sessions.filter(s=>arr.includes(s.date))),top=data.subjects.map(s=>({name:s.name,ms:sumSessions(sessionsFor(s.id).filter(x=>arr.includes(x.date)))})).sort((a,b)=>b.ms-a.ms)[0];html+=section('Your week','analytics');html+='<div class="card"><div style="display:flex;justify-content:space-between;align-items:center"><div><h2>'+duration(weekMs)+'</h2><small class="sub">Total study this week</small></div><span class="pill green">'+(top&&top.ms?esc(top.name)+' leads':'Keep building momentum')+'</span></div>'+barChart(arr)+'</div>'}
 html+='<div style="height:12px"></div><button class="secondary-btn" data-action="quick-session">＋ Add study time</button>';
 return html;
}
function priorityRank(t){let r={High:0,Medium:1,Low:2};return r[t.priority]===undefined?1:r[t.priority]}
function taskRow(t){return '<div class="task-row"><button class="check '+(t.done?'done':'')+'" data-action="toggle-task" data-id="'+t.id+'">'+(t.done?'✓':'')+'</button><div class="task-info"><b style="'+(t.done?'text-decoration:line-through;color:#aaa':'')+'">'+esc(t.title)+'</b><small>'+esc(subjectName(t.subjectId))+' · '+esc(t.category||'Other')+'</small></div><i class="priority '+String(t.priority||'Medium').toLowerCase()+'"></i><button class="text-btn" data-action="edit-task" data-id="'+t.id+'">•••</button></div>'}
function lastDays(n){let a=[];for(let i=n-1;i>=0;i--){let d=new Date();d.setDate(d.getDate()-i);a.push(dayKey(d))}return a}
function barChart(keys){let values=keys.map(k=>sumSessions(sessionsOn(k))),max=Math.max(1,...values);return '<div class="chart">'+keys.map((k,i)=>'<div class="bar-col"><em>'+(values[i]?duration(values[i]):'')+'</em><div class="bar '+(k===dayKey()?'today':'')+'" style="height:'+Math.max(3,values[i]/max*74)+'px"></div><small>'+dateFrom(k).toLocaleDateString(undefined,{weekday:'short'}).slice(0,2)+'</small></div>').join('')+'</div>'}
function tasksView(){
 let list=data.tasks.filter(t=>taskFilter==='all'||(taskFilter==='today'?t.date===dayKey():taskFilter==='pending'?!t.done:taskFilter==='done'?t.done:t.date>=dayKey())).filter(t=>!taskQuery||t.title.toLowerCase().includes(taskQuery.toLowerCase())||subjectName(t.subjectId).toLowerCase().includes(taskQuery.toLowerCase())).sort((a,b)=>a.date.localeCompare(b.date)||(a.startTime||'').localeCompare(b.startTime||''));
 let done=list.filter(t=>t.done).length;
 return pageTitle('Tasks & plans','Small steps make a strong result.','<button class="primary-btn" data-action="new-task">＋ Add task</button>')+
 '<input class="searchbox" id="taskSearch" placeholder="Search tasks or subjects…" value="'+esc(taskQuery)+'" style="width:100%;padding:12px 14px;border:1px solid var(--line);border-radius:14px;background:white;margin-bottom:12px">'+
 '<div class="tabs">'+[['today','Today'],['upcoming','Upcoming'],['pending','Pending'],['done','Completed'],['all','All']].map(x=>'<button class="tab '+(taskFilter===x[0]?'active':'')+'" data-action="task-filter" data-value="'+x[0]+'">'+x[1]+'</button>').join('')+'</div>'+
 '<div class="stats-grid"><div class="stat-card"><strong>'+done+'</strong><small>Completed in view</small></div><div class="stat-card"><strong>'+(list.length-done)+'</strong><small>Still to do</small></div></div>'+
 '<div class="card list-card" style="margin-top:14px">'+(list.length?list.map(taskRow).join(''):empty('No tasks here yet. Add a task to plan your next study session.','☷'))+'</div>'+
 '<div class="section-head"><h2>Weekly planner</h2><button data-action="timetable">Open timetable →</button></div><div class="card">'+weekStrip()+'</div>';
}
function weekStrip(){let days=lastDays(7);return '<div class="week-grid">'+days.map(k=>'<div class="day-col"><b>'+dateFrom(k).toLocaleDateString(undefined,{weekday:'short',day:'numeric'})+'</b><div class="sub" style="margin-top:6px">'+data.tasks.filter(t=>t.date===k&&!t.done).length+' pending</div><div class="sub">'+data.tasks.filter(t=>t.date===k&&t.done).length+' done</div></div>').join('')+'</div>'}
function timerView(){
 const t=data.timer,study=t.mode==='study',sub=t.subjectId?subjectName(t.subjectId):'Choose a subject';
 return pageTitle('Study timer','One focused session at a time.')+
 '<div class="field"><label>STUDY SUBJECT</label><select id="timerSubject" '+(t.status==='running'?'disabled':'')+'>'+subjectOptions(t.subjectId)+'</select></div>'+
 '<div class="timer-card"><div class="timer-mode">'+(study?'FOCUS SESSION':t.mode==='short'?'SHORT BREAK':'LONG BREAK')+'</div><div class="timer-ring" style="--timer-pct:'+timerPct()+'%"><div class="timer-time" id="timerTime">'+timeFmt(currentRemaining())+'</div></div><div class="timer-subject">'+esc(sub)+'</div><div class="timer-controls">'+timerButtons()+'</div><div style="margin-top:15px;color:#a9a19a;font-size:10px">Focus '+data.settings.study+' min · Short break '+data.settings.shortBreak+' min · Long break '+data.settings.longBreak+' min</div></div>'+
 '<div class="section-head"><h2>Session history</h2><button data-action="analytics">All analytics →</button></div><div class="card list-card">'+(data.sessions.slice().sort((a,b)=>b.startedAt-a.startedAt).slice(0,5).map(s=>'<div class="task-row"><span class="subject-icon" style="background:'+subjectColor(s.subjectId)+'">◷</span><div class="task-info"><b>'+esc(subjectName(s.subjectId))+'</b><small>'+fmtDate(s.date)+' · '+(s.type==='pomodoro'?'Pomodoro':'Manual / focus')+'</small></div><b>'+duration(s.durationMs)+'</b></div>').join('')||empty('Your completed study sessions will appear here.','◷'))+'</div>';
}
function currentRemaining(){let t=data.timer;if(t.status==='running')return Math.max(0,t.endAt-Date.now());return t.remainingMs}
function timerPct(){let t=data.timer,full=(t.mode==='study'?data.settings.study:t.mode==='short'?data.settings.shortBreak:data.settings.longBreak)*60000;return Math.max(0,Math.min(100,100-currentRemaining()/full*100))}
function timerButtons(){let s=data.timer.status;if(s==='running')return '<button class="primary-btn timer-white" data-action="pause-timer">Pause</button><button class="timer-outline" data-action="reset-timer">Reset</button><button class="timer-outline" data-action="skip-timer">Skip</button>';if(s==='paused')return '<button class="primary-btn timer-white" data-action="resume-timer">Resume</button><button class="timer-outline" data-action="reset-timer">Reset</button><button class="timer-outline" data-action="skip-timer">Skip</button>';return '<button class="primary-btn timer-white" data-action="start-timer">'+(s==='idle'?'Start focus':'Start '+(data.timer.mode==='study'?'focus':'break'))+'</button><button class="timer-outline" data-action="reset-timer">Reset</button>'}
function startTicker(){stopTicker();timerTick=setInterval(()=>{if(tab!=='timer')return;let t=data.timer;if(t.status==='running'){if(currentRemaining()<=0){finishTimer(true);return}let el=document.getElementById('timerTime');if(el)el.textContent=timeFmt(currentRemaining());let ring=document.querySelector('.timer-ring');if(ring)ring.style.setProperty('--timer-pct',timerPct()+'%')}},500)}
function stopTicker(){if(timerTick){clearInterval(timerTick);timerTick=null}}
function beginTimer(){let t=data.timer;if(t.mode==='study'&&!t.subjectId){toast('Choose a subject before starting.');return}if(t.mode==='study'&&t.status==='idle'){t.sessionId=id();t.startedAt=Date.now()}t.status='running';t.endAt=Date.now()+t.remainingMs;save();if(window.BeReady)BeReady.scheduleReminder(t.endAt,'BeReady timer finished',t.mode==='study'?'Your focus session is complete. Take a break!':'Your break is over. Ready to focus?',771);render()}
function pauseTimer(){let t=data.timer;t.remainingMs=currentRemaining();t.status='paused';t.endAt=0;if(window.BeReady)BeReady.cancelReminder(771);save();render()}
function resetTimer(){let t=data.timer;if(window.BeReady)BeReady.cancelReminder(771);t.status='idle';t.endAt=0;t.startedAt=0;t.sessionId='';t.remainingMs=modeDuration(t.mode);save();render()}
function modeDuration(mode){return (mode==='study'?data.settings.study:mode==='short'?data.settings.shortBreak:data.settings.longBreak)*60000}
function finishTimer(full){let t=data.timer;if(t.mode==='study'&&t.sessionId){let elapsed=full?Date.now()-t.startedAt:Math.max(0,modeDuration('study')-currentRemaining());if(elapsed>=60000&&!data.sessions.some(s=>s.id===t.sessionId)){data.sessions.push({id:t.sessionId,subjectId:t.subjectId,date:dayKey(new Date(t.startedAt)),startedAt:t.startedAt,endedAt:Date.now(),durationMs:full?modeDuration('study'):elapsed,type:'pomodoro',description:'Pomodoro focus'});}}
 if(window.BeReady){BeReady.cancelReminder(771);if(data.settings.vibrate)BeReady.vibrate(250);BeReady.notifyNow(full?'Session complete':'Timer skipped',full?'Great work. Take a short break.':'Your timer has been stopped.')}
 if(t.mode==='study'){let count=sessionsOn(dayKey()).filter(s=>s.type==='pomodoro').length;t.mode=(count>0&&count%data.settings.longAfter===0)?'long':'short'}else t.mode='study';
 t.status='idle';t.remainingMs=modeDuration(t.mode);t.endAt=0;t.startedAt=0;t.sessionId='';save();render();toast(full?'Session saved. Well done!':'Timer skipped.')}
function libraryView(){
 return pageTitle('Your library','Notes, papers and revision resources.','<button class="primary-btn" data-action="new-note">＋ Note</button>')+
 '<div class="stats-grid"><div class="stat-card"><div class="stat-icon">▤</div><strong>'+data.notes.length+'</strong><small>Saved notes</small></div><div class="stat-card"><div class="stat-icon">PDF</div><strong>'+data.documents.length+'</strong><small>Documents & papers</small></div></div>'+
 '<div class="section-head"><h2>Study notes</h2><button data-action="new-note">Create note →</button></div><div class="card">'+(data.notes.length?data.notes.slice().reverse().map(n=>'<div class="doc-row"><div class="doc-icon">✎</div><div><b>'+esc(n.title)+'</b><small>'+esc(subjectName(n.subjectId))+' · '+fmtDate(n.date)+'</small></div><button class="text-btn" data-action="edit-note" data-id="'+n.id+'">Edit</button></div>').join(''):empty('Keep your explanations, summaries and revision notes here.','✎'))+'</div>'+
 '<div class="section-head"><h2>PDFs & past papers</h2><button data-action="pick-document">＋ Add file</button></div><div class="card">'+(data.documents.length?data.documents.map(d=>'<div class="doc-row"><div class="doc-icon">PDF</div><div><b>'+esc(d.name)+'</b><small>'+esc(subjectName(d.subjectId))+' · '+esc(d.kind||'Resource')+'</small></div><button class="text-btn" data-action="open-document" data-id="'+d.id+'">Open</button><button class="text-btn" data-action="delete-document" data-id="'+d.id+'">×</button></div>').join(''):empty('Import PDFs, past papers and reference files from your device.','▤'))+'</div>'+
 '<div class="section-head"><h2>Quick revision</h2><button data-action="flashcards">Practice →</button></div><div class="card"><b>'+data.flashcards.length+' flashcards</b><p class="sub">Create question-and-answer cards for formulas, definitions and key facts.</p><button class="secondary-btn" data-action="new-flashcard">＋ Add flashcard</button></div>';
}
function moreView(){
 return pageTitle('Study tools','Everything you need to stay exam-ready.')+
 '<div class="stats-grid">'+moreTile('◴','Analytics','Study trends and streaks','analytics')+moreTile('▦','Timetable','Plan your week','timetable')+moreTile('▣','Study calendar','See your study days','calendar')+moreTile('✦','Flashcards','Active recall practice','flashcards')+moreTile('✓','Syllabus tracker','Track topics covered','syllabus')+moreTile('∑','Formula bank','Save key formulas','formulas')+moreTile('⚙','Settings','Targets and preferences','open-settings')+moreTile('◉','Manage subjects','Add your own subjects','subjects')+'</div>'+
 '<div class="section-head"><h2>Exam preparation</h2></div><div class="card"><h3>Past-paper practice</h3><p class="sub">Schedule timed papers, record marks and review weak areas after each attempt.</p><button class="secondary-btn" data-action="new-paper">＋ Record paper attempt</button></div>';
}
function moreTile(icon,title,desc,action){return '<button class="stat-card" style="text-align:left" data-action="'+action+'"><div class="stat-icon">'+icon+'</div><b>'+title+'</b><small>'+desc+'</small></button>'}
function analyticsView(){let keys=analyticsRange==='all'?allStudyDays():lastDays(analyticsRange),total=sumSessions(data.sessions.filter(s=>keys.includes(s.date))),st=streak(),days=allStudyDays(),avg=days.length?sumSessions(data.sessions)/days.length:0,top=data.subjects.map(s=>({s,ms:sumSessions(sessionsFor(s.id))})).sort((a,b)=>b.ms-a.ms)[0];return pageTitle('Study analytics','Progress measured in effort, not pressure.')+'<div class="tabs">'+[7,30,90,'all'].map(n=>'<button class="tab '+(analyticsRange===n?'active':'')+'" data-action="range" data-value="'+n+'">'+(n==='all'?'All time':n+' days')+'</button>').join('')+'</div><div class="hero"><div class="eyebrow">RECORDED STUDY TIME</div><h2>'+duration(total)+'</h2><p>Across the selected period</p></div><div class="stats-grid"><div class="stat-card"><strong>'+days.length+'</strong><small>Study days</small></div><div class="stat-card"><strong>'+st.cur+' days</strong><small>Current streak</small></div><div class="stat-card"><strong>'+st.best+' days</strong><small>Longest streak</small></div><div class="stat-card"><strong>'+duration(avg)+'</strong><small>Average per study day</small></div></div><div class="section-head"><h2>Daily trend</h2></div><div class="card">'+barChart(keys.slice(-14))+'</div><div class="section-head"><h2>Subject distribution</h2></div><div class="card">'+(data.subjects.map(s=>{let ms=sumSessions(sessionsFor(s.id)),p=sumSessions(data.sessions)?ms/sumSessions(data.sessions)*100:0;return '<div style="margin:12px 0"><div style="display:flex;justify-content:space-between"><b>'+esc(s.name)+'</b><small>'+duration(ms)+'</small></div><div class="mini-track"><i style="width:'+p+'%;background:'+s.color+'"></i></div></div>'}).join('')||empty('Add a subject to begin tracking.'))+'</div><p class="sub" style="text-align:center;margin-top:15px">Most studied: '+(top&&top.ms?esc(top.s.name):'Not enough data yet')+'</p>'}
function calendarView(){let y=calendarDate.getFullYear(),m=calendarDate.getMonth(),first=new Date(y,m,1).getDay(),num=new Date(y,m+1,0).getDate(),keys=allStudyDays();let html=pageTitle('Study calendar','A gentle view of your consistency.')+'<div class="card"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px"><button class="ghost-btn" data-action="cal-prev">‹</button><b>'+calendarDate.toLocaleDateString(undefined,{month:'long',year:'numeric'})+'</b><button class="ghost-btn" data-action="cal-next">›</button></div><div class="calendar">'+['S','M','T','W','T','F','S'].map(x=>'<div class="weekday">'+x+'</div>').join('')+Array(first).fill('<div></div>').join('')+Array.from({length:num},(_,i)=>{let d=new Date(y,m,i+1),k=dayKey(d);return '<div class="'+(keys.includes(k)?'has-study ':'')+(selectedCalendar===k?'selected':'')+'" data-action="calendar-day" data-value="'+k+'">'+(i+1)+'</div>'}).join('')+'</div></div>';if(selectedCalendar){let ss=sessionsOn(selectedCalendar);html+='<div class="section-head"><h2>'+fmtDate(selectedCalendar)+'</h2><span class="pill">'+duration(sumSessions(ss))+'</span></div><div class="card list-card">'+(ss.length?ss.map(s=>'<div class="task-row"><div class="task-info"><b>'+esc(subjectName(s.subjectId))+'</b><small>'+new Date(s.startedAt).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'})+' · '+esc(s.description||s.type)+'</small></div><b>'+duration(s.durationMs)+'</b></div>').join(''):empty('No study recorded on this date.'))+'</div>'}return html}
function timetableView(){let d=selectedDay,events=data.events.slice().sort((a,b)=>a.day-b.day||a.start.localeCompare(b.start));return pageTitle('Weekly timetable','Build a repeatable rhythm for your week.','<button class="primary-btn" data-action="new-event">＋ Event</button>')+'<div class="tabs">'+['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((x,i)=>'<button class="tab '+(d===i?'active':'')+'" data-action="day-select" data-value="'+i+'">'+x+'</button>').join('')+'</div><div class="card">'+(events.filter(e=>e.day===d).length?events.filter(e=>e.day===d).map(eventRow).join(''):empty('No events for this day. Add a study block.','▦'))+'</div><div class="section-head"><h2>Full week</h2></div><div class="card"><div class="week-grid">'+['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((x,i)=>'<div class="day-col"><b>'+x+'</b>'+events.filter(e=>e.day===i).map(e=>'<div class="event-chip">'+esc(e.start)+'<br>'+esc(e.title||subjectName(e.subjectId))+'</div>').join('')+'</div>').join('')+'</div></div>'}
let selectedDay=new Date().getDay();
function eventRow(e){return '<div class="task-row"><span class="subject-icon" style="background:'+subjectColor(e.subjectId)+'">◷</span><div class="task-info"><b>'+esc(e.title||subjectName(e.subjectId))+'</b><small>'+esc(subjectName(e.subjectId))+' · '+esc(e.start)+'–'+esc(e.end)+(e.reminder?' · reminder':'')+'</small></div><button class="text-btn" data-action="edit-event" data-id="'+e.id+'">Edit</button></div>'}
function nextEventDate(e){let d=new Date();let delta=(e.day-d.getDay()+7)%7;let at=new Date(d.getFullYear(),d.getMonth(),d.getDate()+delta,...e.start.split(':').map(Number),0,0).getTime();if(at<=Date.now())at+=7*86400000;return at}
function flashcardsView(){let list=data.flashcards;if(!list.length)return pageTitle('Flashcards','Use active recall to strengthen memory.')+'<div class="card">'+empty('Create your first flashcard.','✦')+'<button class="primary-btn" data-action="new-flashcard">Add flashcard</button></div>';let f=list[flashIndex%list.length];return pageTitle('Flashcard practice','Recall first. Reveal the answer after.')+'<div class="sub" style="text-align:center;margin:15px">Card '+(flashIndex%list.length+1)+' of '+list.length+'</div><div class="flashcard" data-action="reveal-card">'+esc(flashReveal?f.answer:f.question)+'</div><p class="sub" style="text-align:center">'+(flashReveal?'Answer':'Tap the card to reveal the answer')+'</p><div class="modal-actions"><button class="ghost-btn" data-action="prev-card">Previous</button><button class="primary-btn" data-action="next-card">Next card</button></div><div class="section-head"><h2>Card library</h2><button data-action="new-flashcard">＋ Add</button></div><div class="card list-card">'+list.map(f=>'<div class="task-row"><div class="task-info"><b>'+esc(f.question)+'</b><small>'+esc(subjectName(f.subjectId))+'</small></div><button class="text-btn" data-action="delete-flashcard" data-id="'+f.id+'">×</button></div>').join('')+'</div>'}
function syllabusView(){return pageTitle('Syllabus tracker','Mark topics as you learn and revise.')+'<button class="primary-btn" data-action="new-topic">＋ Add topic</button><div class="card" style="margin-top:14px">'+(data.syllabus.length?data.syllabus.map(x=>'<div class="task-row"><button class="check '+(x.done?'done':'')+'" data-action="toggle-topic" data-id="'+x.id+'">'+(x.done?'✓':'')+'</button><div class="task-info"><b>'+esc(x.title)+'</b><small>'+esc(subjectName(x.subjectId))+' · '+esc(x.unit||'Topic')+'</small></div><button class="text-btn" data-action="delete-topic" data-id="'+x.id+'">×</button></div>').join(''):empty('Add topics from your A/L syllabus to track coverage.','✓'))+'</div>'}
function formulasView(){let fs=data.notes.filter(n=>n.kind==='formula');return pageTitle('Formula bank','Keep essential equations easy to revisit.')+'<button class="primary-btn" data-action="new-formula">＋ Add formula</button><div class="card" style="margin-top:14px">'+(fs.length?fs.map(f=>'<div class="doc-row"><div class="doc-icon">∑</div><div><b>'+esc(f.title)+'</b><small>'+esc(f.content)+'</small></div><button class="text-btn" data-action="edit-note" data-id="'+f.id+'">Edit</button></div>').join(''):empty('Save equations, constants and quick reminders here.','∑'))+'</div>'}
function subjectsView(){return pageTitle('Your subjects','Add and personalize your A/L subjects.','<button class="primary-btn" data-action="new-subject">＋ Subject</button>')+'<div class="card">'+data.subjects.map(s=>'<div class="doc-row"><div class="doc-icon" style="background:'+s.color+'">'+esc(s.icon)+'</div><div><b>'+esc(s.name)+'</b><small>'+duration(sumSessions(sessionsFor(s.id)))+' tracked</small></div><button class="text-btn" data-action="edit-subject" data-id="'+s.id+'">Edit</button></div>').join('')+'</div>'}
function settingsView(){return pageTitle('Settings','Make BeReady work the way you study.')+'<form id="settingsForm"><div class="card"><h3>Study targets</h3><div class="form-row"><div class="field"><label>DAILY TARGET (HOURS)</label><input name="dailyTarget" type="number" min="0.5" max="18" step=".5" value="'+data.settings.dailyTarget+'"></div><div class="field"><label>WEEKLY TARGET (HOURS)</label><input name="weeklyTarget" type="number" min="1" max="100" value="'+data.settings.weeklyTarget+'"></div></div><h3>Pomodoro durations</h3><div class="form-row"><div class="field"><label>FOCUS (MIN)</label><input name="study" type="number" min="1" max="180" value="'+data.settings.study+'"></div><div class="field"><label>SHORT BREAK</label><input name="shortBreak" type="number" min="1" max="60" value="'+data.settings.shortBreak+'"></div><div class="field"><label>LONG BREAK</label><input name="longBreak" type="number" min="1" max="90" value="'+data.settings.longBreak+'"></div><div class="field"><label>LONG BREAK AFTER</label><input name="longAfter" type="number" min="2" max="10" value="'+data.settings.longAfter+'"></div></div><label style="display:flex;gap:10px;align-items:center;margin:12px 0"><input type="checkbox" name="sound" '+(data.settings.sound?'checked':'')+'> Timer completion sound (when supported)</label><label style="display:flex;gap:10px;align-items:center;margin:12px 0"><input type="checkbox" name="vibrate" '+(data.settings.vibrate?'checked':'')+'> Vibrate on completion</label><button class="primary-btn" type="submit" style="width:100%;margin-top:14px">Save settings</button></div></form><div class="section-head"><h2>Dashboard sections</h2></div><div class="card">'+Object.entries({subjects:'Subject overview',tasks:"Today's tasks",timetable:'Next timetable event',weekly:'Weekly study chart'}).map(([k,v])=>'<label style="display:flex;justify-content:space-between;padding:10px 0">'+v+'<input type="checkbox" data-action="dashboard-toggle" data-id="'+k+'" '+(data.dashboard[k]?'checked':'')+'></label>').join('')+'</div><div class="section-head"><h2>Your data</h2></div><div class="card"><p class="sub">Your study records are stored locally on this device. Export a backup before changing phones.</p><button class="secondary-btn" data-action="export-data">Export backup</button> <button class="ghost-btn" data-action="import-data">Import backup</button><input type="file" id="backupInput" accept=".json,application/json" hidden></div><p class="sub" style="text-align:center;margin:18px">BeReady 1.0 · Offline-first A/L companion</p>'}
function renderSubPage(name){tab='more';let root=document.getElementById('screen');root.innerHTML=name==='analytics'?analyticsView():name==='calendar'?calendarView():name==='timetable'?timetableView():name==='flashcards'?flashcardsView():name==='syllabus'?syllabusView():name==='formulas'?formulasView():name==='subjects'?subjectsView():settingsView();document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab))}
function openModal(html){document.getElementById('modalBody').innerHTML=html;document.getElementById('modal').classList.remove('hidden')}
function closeModal(){document.getElementById('modal').classList.add('hidden')}
function field(label,name,value='',type='text',extra=''){return '<div class="field"><label>'+label+'</label><input name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></div>'}
function taskForm(t={}){openModal('<h2>'+(t.id?'Edit task':'Create a task')+'</h2><form id="taskForm"><input type="hidden" name="id" value="'+(t.id||'')+'">'+field('TASK TITLE','title',t.title||'','text','required')+'<div class="field"><label>SUBJECT</label><select name="subjectId">'+subjectOptions(t.subjectId||'')+'</select></div>'+field('DESCRIPTION','description',t.description||'')+'<div class="form-row">'+field('DATE','date',t.date||dayKey(),'date','required')+field('START TIME','startTime',t.startTime||'','time')+'</div><div class="form-row"><div class="field"><label>ESTIMATED DURATION (MIN)</label><input name="estimate" type="number" min="0" value="'+(t.estimate||45)+'"></div><div class="field"><label>PRIORITY</label><select name="priority">'+['Low','Medium','High'].map(x=>'<option '+((t.priority||'Medium')===x?'selected':'')+'>'+x+'</option>').join('')+'</select></div></div><div class="field"><label>CATEGORY</label><select name="category">'+['Theory studying','Revision','MCQ practice','Structured questions','Essay questions','Past papers','Homework','Other'].map(x=>'<option '+((t.category||'Theory studying')===x?'selected':'')+'>'+x+'</option>').join('')+'</select></div><label style="display:flex;gap:8px;align-items:center"><input type="checkbox" name="reminder" '+(t.reminder?'checked':'')+'> Remind me at the start time</label><div class="modal-actions"><button type="button" class="ghost-btn" data-action="close-modal">Cancel</button><button class="primary-btn" type="submit">Save task</button></div>'+(t.id?'<button type="button" class="text-btn" style="margin-top:14px" data-action="delete-task" data-id="'+t.id+'">Delete task</button>':'')+'</form>')}
function sessionForm(){openModal('<h2>Add study time</h2><form id="sessionForm"><div class="field"><label>SUBJECT</label><select name="subjectId" required>'+subjectOptions()+'</select></div><div class="form-row">'+field('DATE','date',dayKey(),'date','required')+field('HOURS','hours','1','number','min="0" max="24"')+field('MINUTES','minutes','0','number','min="0" max="59"')+'</div>'+field('START TIME (OPTIONAL)','startTime','','time')+field('DESCRIPTION (OPTIONAL)','description','')+'<div class="modal-actions"><button type="button" class="ghost-btn" data-action="close-modal">Cancel</button><button class="primary-btn">Save time</button></div></form>')}
function noteForm(n={},kind='note'){openModal('<h2>'+(n.id?'Edit':'Create')+(kind==='formula'?' formula':' note')+'</h2><form id="noteForm"><input type="hidden" name="id" value="'+(n.id||'')+'"><input type="hidden" name="kind" value="'+(n.kind||kind)+'">'+field('TITLE','title',n.title||'','text','required')+'<div class="field"><label>SUBJECT</label><select name="subjectId">'+subjectOptions(n.subjectId||'')+'</select></div><div class="field"><label>'+(kind==='formula'?'FORMULA / EXPLANATION':'YOUR NOTES')+'</label><textarea name="content" required>'+esc(n.content||'')+'</textarea></div><div class="modal-actions"><button type="button" class="ghost-btn" data-action="close-modal">Cancel</button><button class="primary-btn">Save</button></div>'+(n.id?'<button type="button" class="text-btn" data-action="delete-note" data-id="'+n.id+'">Delete note</button>':'')+'</form>')}
function eventForm(e={}){openModal('<h2>'+(e.id?'Edit timetable event':'New timetable event')+'</h2><form id="eventForm"><input type="hidden" name="id" value="'+(e.id||'')+'">'+field('EVENT TITLE','title',e.title||'Study session','text','required')+'<div class="field"><label>SUBJECT</label><select name="subjectId">'+subjectOptions(e.subjectId||'')+'</select></div><div class="form-row"><div class="field"><label>DAY</label><select name="day">'+['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((x,i)=>'<option value="'+i+'" '+((e.day===undefined?new Date().getDay():e.day)===i?'selected':'')+'>'+x+'</option>').join('')+'</select></div>'+field('START','start',e.start||'08:00','time','required')+'</div><div class="form-row">'+field('END','end',e.end||'09:00','time','required')+'<div class="field"><label>REMINDER</label><select name="reminder"><option value="0">No reminder</option>'+[0,5,10,15,30].filter(x=>x>0).map(x=>'<option value="'+x+'" '+(Number(e.reminder)===x?'selected':'')+'>'+x+' min before</option>').join('')+'</select></div></div>'+field('DESCRIPTION','description',e.description||'')+'<div class="modal-actions"><button type="button" class="ghost-btn" data-action="close-modal">Cancel</button><button class="primary-btn">Save event</button></div>'+(e.id?'<button type="button" class="text-btn" data-action="delete-event" data-id="'+e.id+'">Delete event</button>':'')+'</form>')}
function flashForm(){openModal('<h2>New flashcard</h2><form id="flashForm"><div class="field"><label>SUBJECT</label><select name="subjectId">'+subjectOptions()+'</select></div><div class="field"><label>QUESTION / FRONT</label><textarea name="question" required></textarea></div><div class="field"><label>ANSWER / BACK</label><textarea name="answer" required></textarea></div><div class="modal-actions"><button type="button" class="ghost-btn" data-action="close-modal">Cancel</button><button class="primary-btn">Save card</button></div></form>')}
function topicForm(){openModal('<h2>Add syllabus topic</h2><form id="topicForm"><div class="field"><label>SUBJECT</label><select name="subjectId">'+subjectOptions()+'</select></div>'+field('TOPIC / UNIT','title','','text','required')+field('UNIT / CHAPTER (OPTIONAL)','unit')+'<div class="modal-actions"><button type="button" class="ghost-btn" data-action="close-modal">Cancel</button><button class="primary-btn">Add topic</button></div></form>')}
function subjectForm(s={}){openModal('<h2>'+(s.id?'Edit subject':'Add subject')+'</h2><form id="subjectForm"><input type="hidden" name="id" value="'+(s.id||'')+'">'+field('SUBJECT NAME','name',s.name||'','text','required')+'<div class="form-row">'+field('ICON','icon',s.icon||'✦')+'<div class="field"><label>ACCENT COLOR</label><input name="color" type="color" value="'+(s.color||'#e6e9ff')+'"></div></div><div class="modal-actions"><button type="button" class="ghost-btn" data-action="close-modal">Cancel</button><button class="primary-btn">Save subject</button></div>'+(s.id?'<button type="button" class="text-btn" data-action="delete-subject" data-id="'+s.id+'">Delete subject</button>':'')+'</form>')}
function handleForm(form){let fd=new FormData(form),v={};fd.forEach((value,key)=>{v[key]=value});if(form.id==='taskForm'){let old=data.tasks.find(x=>x.id===v.id),t={...old,...v,id:v.id||id(),done:old?old.done:false,reminder:form.reminder.checked};if(!t.title.trim())return;let i=data.tasks.findIndex(x=>x.id===t.id);if(i>=0)data.tasks[i]=t;else data.tasks.push(t);if(t.reminder&&t.startTime){let at=new Date(t.date+'T'+t.startTime).getTime();if(window.BeReady&&at>Date.now())BeReady.scheduleReminder(at,'BeReady task',t.title,hashId(t.id))}save();closeModal();render();toast('Task saved')}
 if(form.id==='sessionForm'){let ms=(Number(v.hours)||0)*3600000+(Number(v.minutes)||0)*60000;if(!v.subjectId||ms<=0){toast('Choose a subject and enter a duration.');return}let start=v.startTime?new Date(v.date+'T'+v.startTime).getTime():dateFrom(v.date).getTime();data.sessions.push({id:id(),subjectId:v.subjectId,date:v.date,startedAt:start,endedAt:start+ms,durationMs:ms,type:'manual',description:v.description||'Manual study entry'});save();closeModal();render();toast('Study time added')}
 if(form.id==='noteForm'){let n={id:v.id||id(),title:v.title,subjectId:v.subjectId,content:v.content,date:dayKey(),kind:v.kind||'note'};let i=data.notes.findIndex(x=>x.id===n.id);if(i>=0)data.notes[i]=n;else data.notes.push(n);save();closeModal();render();toast('Saved to library')}
 if(form.id==='eventForm'){if(v.end<=v.start){toast('End time must be after start time.');return}let e={...v,id:v.id||id(),day:Number(v.day),reminder:Number(v.reminder)};let i=data.events.findIndex(x=>x.id===e.id);if(i>=0)data.events[i]=e;else data.events.push(e);scheduleEvent(e);save();closeModal();render();toast('Timetable updated')}
 if(form.id==='flashForm'){data.flashcards.push({id:id(),...v});save();closeModal();renderSubPage('flashcards');toast('Flashcard added')}
 if(form.id==='topicForm'){data.syllabus.push({id:id(),...v,done:false});save();closeModal();renderSubPage('syllabus')}
 if(form.id==='subjectForm'){let s={id:v.id||id(),name:v.name,icon:v.icon||'✦',color:v.color||'#e6e9ff'};let i=data.subjects.findIndex(x=>x.id===s.id);if(i>=0)data.subjects[i]=s;else data.subjects.push(s);save();closeModal();renderSubPage('subjects')}
}
function hashId(s){let h=0;for(let i=0;i<s.length;i++)h=(h*31+s.charCodeAt(i))|0;return Math.abs(h)}
function scheduleEvent(e){if(!window.BeReady||!e.reminder)return;let at=nextEventDate(e)-e.reminder*60000;if(at>Date.now())BeReady.scheduleReminder(at,'Upcoming: '+e.title,subjectName(e.subjectId)+' starts in '+e.reminder+' minutes',hashId(e.id))}
function goBackInApp(){if(!document.getElementById('modal').classList.contains('hidden')){closeModal();return}tab='home';render()}
document.addEventListener('click',e=>{
 let tabBtn=e.target.closest('[data-tab]');if(tabBtn){tab=tabBtn.dataset.tab;render();return}
 let el=e.target.closest('[data-action]');if(!el)return;let a=el.dataset.action,idv=el.dataset.id;
 if(a==='close-modal'){closeModal();return}if(a==='new-task'){taskForm();return}if(a==='edit-task'){taskForm(data.tasks.find(x=>x.id===idv));return}if(a==='delete-task'){data.tasks=data.tasks.filter(x=>x.id!==idv);save();closeModal();render();toast('Task deleted');return}
 if(a==='toggle-task'){let t=data.tasks.find(x=>x.id===idv);if(t)t.done=!t.done;save();render();return}if(a==='task-filter'){taskFilter=el.dataset.value;render();return}
 if(a==='quick-session'){sessionForm();return}if(a==='new-note'){noteForm();return}if(a==='edit-note'){noteForm(data.notes.find(x=>x.id===idv));return}if(a==='delete-note'){data.notes=data.notes.filter(x=>x.id!==idv);save();closeModal();render();return}
 if(a==='pick-document'){if(window.BeReady)BeReady.chooseDocument();else toast('File import is available in the Android app.');return}
 if(a==='open-document'){let d=data.documents.find(x=>x.id===idv);if(d&&window.BeReady)BeReady.openDocument(d.uri);else if(d)window.open(d.uri,'_blank');return}
 if(a==='delete-document'){data.documents=data.documents.filter(x=>x.id!==idv);save();render();return}
 if(a==='new-event'){eventForm();return}if(a==='edit-event'){eventForm(data.events.find(x=>x.id===idv));return}if(a==='delete-event'){data.events=data.events.filter(x=>x.id!==idv);if(window.BeReady)BeReady.cancelReminder(hashId(idv));save();closeModal();renderSubPage('timetable');return}
 if(a==='start-timer'){if(data.timer.mode==='study'&&data.timer.status==='idle'){let sel=document.getElementById('timerSubject');if(sel)data.timer.subjectId=sel.value}beginTimer();return}if(a==='pause-timer'){pauseTimer();return}if(a==='resume-timer'){beginTimer();return}if(a==='reset-timer'){resetTimer();return}if(a==='skip-timer'){finishTimer(false);return}
 if(a==='analytics'){renderSubPage('analytics');return}if(a==='calendar'){renderSubPage('calendar');return}if(a==='timetable'){renderSubPage('timetable');return}if(a==='flashcards'){renderSubPage('flashcards');return}if(a==='syllabus'){renderSubPage('syllabus');return}if(a==='formulas'){renderSubPage('formulas');return}if(a==='subjects'){renderSubPage('subjects');return}if(a==='open-settings'){renderSubPage('settings');return}
 if(a==='range'){analyticsRange=el.dataset.value==='all'?'all':Number(el.dataset.value);renderSubPage('analytics');return}
 if(a==='cal-prev'||a==='cal-next'){calendarDate.setMonth(calendarDate.getMonth()+(a==='cal-prev'?-1:1));renderSubPage('calendar');return}if(a==='calendar-day'){selectedCalendar=el.dataset.value;renderSubPage('calendar');return}
 if(a==='day-select'){selectedDay=Number(el.dataset.value);renderSubPage('timetable');return}
 if(a==='new-flashcard'){flashForm();return}if(a==='reveal-card'){flashReveal=!flashReveal;renderSubPage('flashcards');return}if(a==='next-card'){flashIndex++;flashReveal=false;renderSubPage('flashcards');return}if(a==='prev-card'){flashIndex=Math.max(0,flashIndex-1);flashReveal=false;renderSubPage('flashcards');return}if(a==='delete-flashcard'){data.flashcards=data.flashcards.filter(x=>x.id!==idv);save();renderSubPage('flashcards');return}
 if(a==='new-topic'){topicForm();return}if(a==='toggle-topic'){let x=data.syllabus.find(x=>x.id===idv);if(x)x.done=!x.done;save();renderSubPage('syllabus');return}if(a==='delete-topic'){data.syllabus=data.syllabus.filter(x=>x.id!==idv);save();renderSubPage('syllabus');return}
 if(a==='new-subject'){subjectForm();return}if(a==='edit-subject'){subjectForm(data.subjects.find(x=>x.id===idv));return}if(a==='delete-subject'){if(data.sessions.some(s=>s.subjectId===idv)||data.tasks.some(t=>t.subjectId===idv)){toast('This subject has saved records and cannot be deleted.');return}data.subjects=data.subjects.filter(x=>x.id!==idv);save();closeModal();renderSubPage('subjects');return}
 if(a==='new-formula'){noteForm({},'formula');return}if(a==='new-paper'){taskForm({category:'Past papers',title:'Past paper practice',estimate:180,priority:'High'});return}
 if(a==='export-data'){let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),link=document.createElement('a');link.href=u;link.download='beready-backup-'+dayKey()+'.json';link.click();URL.revokeObjectURL(u);toast('Backup exported');return}
 if(a==='import-data'){document.getElementById('backupInput').click();return}
 if(a==='dashboard-toggle'){data.dashboard[el.dataset.id]=el.checked;save();return}
});
document.addEventListener('submit',e=>{if(e.target.id==='settingsForm'){e.preventDefault();let f=e.target;['dailyTarget','weeklyTarget','study','shortBreak','longBreak','longAfter'].forEach(k=>data.settings[k]=Number(f.elements[k].value)||defaultData.settings[k]);data.settings.sound=f.elements.sound.checked;data.settings.vibrate=f.elements.vibrate.checked;save();toast('Settings saved');renderSubPage('settings');return}if(['taskForm','sessionForm','noteForm','eventForm','flashForm','topicForm','subjectForm'].includes(e.target.id)){e.preventDefault();handleForm(e.target)}});
document.addEventListener('input',e=>{if(e.target.id==='taskSearch'){taskQuery=e.target.value;let pos=e.target.selectionStart;render();let n=document.getElementById('taskSearch');n.focus();n.setSelectionRange(pos,pos)}});
document.addEventListener('change',e=>{if(e.target.id==='timerSubject'){data.timer.subjectId=e.target.value;save()}if(e.target.id==='backupInput'&&e.target.files[0]){let r=new FileReader();r.onload=()=>{try{let x=JSON.parse(r.result);if(!x.sessions||!x.tasks||!x.settings)throw Error();data=Object.assign(defaultData,x);save();render();toast('Backup restored')}catch(err){toast('This backup file is not valid.')}};r.readAsText(e.target.files[0])}});
window.onPickedDocument=function(name,uri){let d={id:id(),name:name,uri:uri,kind:'Resource',subjectId:''};data.documents.push(d);save();if(tab==='library')render();toast('File added to your library')};
window.addEventListener('focus',()=>{if(data.timer.status==='running'&&currentRemaining()<=0)finishTimer(true);else if(tab==='timer')render()});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&data.timer.status==='running'&&currentRemaining()<=0)finishTimer(true)});
setTimeout(()=>{document.getElementById('splash').classList.add('hidden');document.getElementById('app').classList.remove('hidden');render();if(data.timer.status==='running'&&currentRemaining()<=0)finishTimer(true)},550);


/* BeReady reliability and study-workflow enhancements */
data.timer.elapsedMs = Number(data.timer.elapsedMs) || 0;
data.timer.segmentStartedAt = Number(data.timer.segmentStartedAt) || (data.timer.status === 'running' ? Number(data.timer.startedAt)||0 : 0);

beginTimer = function(){
 const t=data.timer;
 if(t.mode==='study'&&!t.subjectId){toast('Choose a subject before starting.');return}
 if(t.status==='idle'&&t.mode==='study'){t.sessionId=id();t.startedAt=Date.now();t.elapsedMs=0}
 t.segmentStartedAt=Date.now();t.status='running';t.endAt=Date.now()+Math.max(0,Number(t.remainingMs)||modeDuration(t.mode));
 save();
 if(window.BeReady)BeReady.scheduleReminder(t.endAt,'BeReady timer finished',t.mode==='study'?'Your focus session is complete. Take a break!':'Your break is over. Ready to focus?',771);
 render();
};
pauseTimer = function(){
 const t=data.timer,now=Date.now();
 if(t.status!=='running')return;
 t.elapsedMs=(Number(t.elapsedMs)||0)+Math.max(0,now-(Number(t.segmentStartedAt)||now));
 t.segmentStartedAt=0;t.remainingMs=currentRemaining();t.status='paused';t.endAt=0;
 if(window.BeReady)BeReady.cancelReminder(771);save();render();
};
resetTimer = function(){
 const t=data.timer;if(window.BeReady)BeReady.cancelReminder(771);
 t.status='idle';t.endAt=0;t.startedAt=0;t.segmentStartedAt=0;t.elapsedMs=0;t.sessionId='';
 t.remainingMs=modeDuration(t.mode);save();render();
};
finishTimer = function(full){
 const t=data.timer,now=Date.now();
 if(t.mode==='study'&&t.sessionId){
  const active=(t.status==='running'?Math.max(0,now-(Number(t.segmentStartedAt)||now)):0);
  const elapsed=Math.max(0,(Number(t.elapsedMs)||0)+active);
  const actual=full?Math.min(modeDuration('study'),elapsed||modeDuration('study')):elapsed;
  if(actual>=60000&&!data.sessions.some(s=>s.id===t.sessionId)){
   data.sessions.push({id:t.sessionId,subjectId:t.subjectId,date:dayKey(new Date(t.startedAt||now)),startedAt:t.startedAt||now,endedAt:now,durationMs:actual,type:'pomodoro',description:'Pomodoro focus'});
  }
 }
 if(window.BeReady){BeReady.cancelReminder(771);if(data.settings.vibrate)BeReady.vibrate(250);if(data.settings.sound)playFinishTone();BeReady.notifyNow(full?'Session complete':'Timer stopped',full?'Great work. Your focus time has been saved.':'Your focus time has been saved.');}
 if(t.mode==='study'){
  const count=sessionsOn(dayKey(new Date(t.startedAt||now))).filter(s=>s.type==='pomodoro').length;
  t.mode=(full&&count>0&&count%Math.max(1,data.settings.longAfter)===0)?'long':'short';
 }else t.mode='study';
 t.status='idle';t.remainingMs=modeDuration(t.mode);t.endAt=0;t.startedAt=0;t.segmentStartedAt=0;t.elapsedMs=0;t.sessionId='';
 save();render();toast(full?'Session saved. Well done!':'Elapsed focus time saved.');
};
function playFinishTone(){
 try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const c=new C(),o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.frequency.value=880;g.gain.value=.07;o.start();o.stop(c.currentTime+.22);o.onended=()=>c.close()}catch(e){}
}
function sessionForm(s={}){
 const ms=Number(s.durationMs)||3600000,dt=s.startedAt?new Date(s.startedAt):new Date();
 openModal('<h2>'+(s.id?'Edit':'Add')+' study time</h2><form id="sessionForm"><input type="hidden" name="id" value="'+esc(s.id||'')+'"><div class="field"><label>SUBJECT</label><select name="subjectId" required>'+subjectOptions(s.subjectId||'')+'</select></div><div class="form-row">'+field('DATE','date',s.date||dayKey(),'date','required')+field('HOURS','hours',String(Math.floor(ms/3600000)),'number','min="0" max="24"')+field('MINUTES','minutes',String(Math.floor(ms/60000)%60),'number','min="0" max="59"')+'</div>'+field('START TIME (OPTIONAL)','startTime',s.startedAt?dt.toTimeString().slice(0,5):'','time')+field('DESCRIPTION (OPTIONAL)','description',s.description||'')+'<div class="modal-actions"><button type="button" class="ghost-btn" data-action="close-modal">Cancel</button><button class="primary-btn">Save time</button></div>'+(s.id?'<button type="button" class="text-btn" data-action="delete-session" data-id="'+esc(s.id)+'">Delete entry</button>':'')+'</form>');
}
const beReadyOriginalHandleForm=handleForm;
handleForm=function(form){
 if(form.id==='sessionForm'){
  const fd=new FormData(form),v={};fd.forEach((x,k)=>v[k]=x);
  const ms=(Number(v.hours)||0)*3600000+(Number(v.minutes)||0)*60000;
  if(!v.subjectId||ms<=0||ms>24*3600000){toast('Choose a subject and enter 1 minute to 24 hours.');return}
  const start=v.startTime?new Date(v.date+'T'+v.startTime).getTime():dateFrom(v.date).getTime();
  const old=data.sessions.find(x=>x.id===v.id);
  const item={...(old||{}),id:v.id||id(),subjectId:v.subjectId,date:v.date,startedAt:start,endedAt:start+ms,durationMs:ms,type:old?old.type:'manual',description:v.description||'Manual study entry'};
  const ix=data.sessions.findIndex(x=>x.id===item.id);if(ix>=0)data.sessions[ix]=item;else data.sessions.push(item);
  save();closeModal();render();toast(old?'Study entry updated':'Study time added');return;
 }
 return beReadyOriginalHandleForm(form);
};
const beReadyOriginalTaskRow=taskRow;
taskRow=function(t){
 return '<div class="task-row"><button class="check '+(t.done?'done':'')+'" data-action="toggle-task" data-id="'+esc(t.id)+'">'+(t.done?'✓':'')+'</button><div class="task-info"><b style="'+(t.done?'text-decoration:line-through;color:#aaa':'')+'">'+esc(t.title)+'</b><small>'+esc(subjectName(t.subjectId))+' · '+esc(t.category||'Other')+' · '+esc(t.date||'')+'</small></div><i class="priority '+String(t.priority||'Medium').toLowerCase()+'"></i><button class="text-btn" data-action="edit-task" data-id="'+esc(t.id)+'">Edit</button><button class="text-btn" data-action="duplicate-task" data-id="'+esc(t.id)+'">＋</button></div>';
};
const beReadyOriginalTimerView=timerView;
timerView=function(){
 let html=beReadyOriginalTimerView();
 const history=data.sessions.slice().sort((a,b)=>(b.startedAt||0)-(a.startedAt||0)).slice(0,8);
 const block='<div class="section-head"><h2>Manage study entries</h2><button data-action="quick-session">＋ Add time</button></div><div class="card list-card">'+(history.length?history.map(s=>'<div class="task-row"><div class="task-info"><b>'+esc(subjectName(s.subjectId))+'</b><small>'+esc(fmtDate(s.date))+' · '+esc(s.description||s.type||'Study')+'</small></div><b>'+duration(s.durationMs)+'</b><button class="text-btn" data-action="edit-session" data-id="'+esc(s.id)+'">Edit</button><button class="text-btn" data-action="delete-session" data-id="'+esc(s.id)+'">×</button></div>').join(''):empty('Your study history will appear here.'))+'</div>';
 return html+block;
};
const beReadyOriginalAnalyticsView=analyticsView;
analyticsView=function(){
 let html=beReadyOriginalAnalyticsView();
 const days=lastDays(7),weekly=sumSessions(data.sessions.filter(s=>days.includes(s.date))),goal=Number(data.settings.weeklyTarget)||0,pct=goal?Math.min(100,weekly/(goal*3600000)*100):0;
 return html+'<div class="section-head"><h2>Weekly target</h2><span class="pill">'+duration(weekly)+' / '+goal+'h</span></div><div class="card"><div class="mini-track" style="height:10px"><i style="width:'+pct+'%;height:10px;background:var(--orange)"></i></div><p class="sub" style="margin-top:9px">'+Math.round(pct)+'% of your weekly goal recorded</p></div>';
};
document.addEventListener('click',function(e){
 const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,k=el.dataset.id;
 if(a==='edit-session'){const s=data.sessions.find(x=>x.id===k);if(s)sessionForm(s);return}
 if(a==='delete-session'){if(!confirm('Delete this study-time entry?'))return;data.sessions=data.sessions.filter(x=>x.id!==k);save();closeModal();render();toast('Study entry deleted');return}
 if(a==='duplicate-task'){const t=data.tasks.find(x=>x.id===k);if(!t)return;const copy={...t,id:id(),done:false,date:dayKey(),title:t.title+' (copy)'};data.tasks.push(copy);save();render();toast('Task duplicated for today');return}
});
